import fs from "fs";
import os from "os";
import path from "path";
import type { DirectoryEntry, SearchMatch } from "./types.js";

const READ_MAX_BYTES = 256 * 1024;
const EXCLUDED_DIRS = new Set(["node_modules", ".git", "dist", "out", ".next", "__pycache__", ".venv", "venv"]);

function resolvePath(target: string): string {
  const p = String(target ?? "").trim();
  return p && path.isAbsolute(p) ? p : path.join(os.homedir(), p || "");
}

export function listDirectory(target: string, limit = 500): { ok: true; path: string; entries: DirectoryEntry[]; truncated: boolean } | { ok: false; error: string } {
  const resolved = resolvePath(target) || os.homedir();
  try {
    const raw = fs.readdirSync(resolved, { withFileTypes: true });
    const entries: DirectoryEntry[] = raw.slice(0, limit).map((entry) => {
      let sizeBytes: number | null = null;
      let modifiedAt: string | null = null;
      try {
        const stat = fs.statSync(path.join(resolved, entry.name));
        sizeBytes = stat.size;
        modifiedAt = stat.mtime.toISOString();
      } catch { /* skip */ }
      return {
        name: entry.name,
        type: entry.isDirectory() ? "directory" : entry.isSymbolicLink() ? "symlink" : "file",
        sizeBytes, modifiedAt,
      };
    });
    return { ok: true, path: resolved, entries, truncated: raw.length > limit };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function readFile(target: string): { ok: true; path: string; content: string; sizeBytes: number } | { ok: false; error: string } {
  const filePath = String(target ?? "").trim();
  if (!filePath) return { ok: false, error: "Missing path." };
  const resolved = path.isAbsolute(filePath) ? filePath : path.join(os.homedir(), filePath);
  try {
    const stat = fs.statSync(resolved);
    if (stat.size > READ_MAX_BYTES) return { ok: false, error: `File too large (${stat.size} bytes, max ${READ_MAX_BYTES}).` };
    const content = fs.readFileSync(resolved, "utf8");
    return { ok: true, path: resolved, content, sizeBytes: stat.size };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function writeFile(target: string, content: string, confirmed: boolean): { ok: true; path: string; bytesWritten: number } | { ok: false; error: string; requiresConfirmation?: true; tier?: string; description?: string } {
  const filePath = String(target ?? "").trim();
  if (!filePath) return { ok: false, error: "Missing path." };
  if (typeof content !== "string") return { ok: false, error: "content must be a string." };
  const resolved = path.isAbsolute(filePath) ? filePath : path.join(os.homedir(), filePath);
  if (!confirmed) return { ok: false, requiresConfirmation: true, tier: "write", description: `Write file: ${resolved}`, error: "Confirmation required." };
  try {
    fs.mkdirSync(path.dirname(resolved), { recursive: true });
    fs.writeFileSync(resolved, content, "utf8");
    return { ok: true, path: resolved, bytesWritten: Buffer.byteLength(content, "utf8") };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function deletePath(target: string, confirmed: boolean): { ok: true; path: string } | { ok: false; error: string; requiresConfirmation?: true; tier?: string; description?: string } {
  const targetPath = String(target ?? "").trim();
  if (!targetPath) return { ok: false, error: "Missing path." };
  const resolved = path.isAbsolute(targetPath) ? targetPath : path.join(os.homedir(), targetPath);
  if (!confirmed) return { ok: false, requiresConfirmation: true, tier: "write", description: `Delete: ${resolved}`, error: "Confirmation required." };
  try {
    const stat = fs.statSync(resolved);
    if (stat.isDirectory()) {
      fs.rmSync(resolved, { recursive: true, force: true });
    } else {
      fs.unlinkSync(resolved);
    }
    return { ok: true, path: resolved };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function createDirectory(target: string): { ok: true; path: string } | { ok: false; error: string } {
  const name = String(target ?? "").trim().replace(/[<>:"/\\|?*]/g, "_");
  if (!name) return { ok: false, error: "Missing path." };
  const projectPath = path.isAbsolute(target) ? target : path.join(os.homedir(), "Documents", name);
  try {
    fs.mkdirSync(projectPath, { recursive: true });
    return { ok: true, path: projectPath };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function glob(searchPath: string, pattern: string, maxResults = 200): { ok: true; path: string; pattern: string; results: string[]; truncated: boolean } | { ok: false; error: string } {
  if (!pattern) return { ok: false, error: "Missing pattern." };
  const resolved = resolvePath(searchPath) || process.cwd();
  const limit = Math.min(maxResults, 1000);

  function globToRegex(glob: string): RegExp {
    const normalized = glob.replace(/\\/g, "/");
    let re = "";
    for (let i = 0; i < normalized.length; i++) {
      const c = normalized[i]!;
      if (c === "*" && normalized[i + 1] === "*") {
        re += ".*"; i++;
        if (normalized[i + 1] === "/") i++;
      } else if (c === "*") re += "[^/]*";
      else if (c === "?") re += "[^/]";
      else if (c === "[") {
        const end = normalized.indexOf("]", i);
        if (end > i) { re += normalized.slice(i, end + 1); i = end; }
        else re += "\\[";
      } else if ("^$+.(){}|\\".includes(c)) re += "\\" + c;
      else re += c;
    }
    return new RegExp("^" + re + "$", process.platform === "win32" ? "i" : "");
  }

  let regex: RegExp;
  try { regex = globToRegex(pattern); }
  catch (err) { return { ok: false, error: `Invalid pattern: ${err instanceof Error ? err.message : String(err)}` }; }

  const results: string[] = [];
  function walk(dir: string, depth: number) {
    if (depth > 12 || results.length >= limit) return;
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (results.length >= limit) return;
      const childPath = path.join(dir, entry.name);
      const relPath = path.relative(resolved, childPath).replace(/\\/g, "/");
      if (entry.isDirectory()) {
        if (EXCLUDED_DIRS.has(entry.name)) continue;
        if (regex.test(relPath)) results.push(relPath + "/");
        walk(childPath, depth + 1);
      } else if (entry.isFile() && regex.test(relPath)) {
        results.push(relPath);
      }
    }
  }

  try {
    if (!fs.statSync(resolved).isDirectory()) return { ok: false, error: "path must be a directory." };
    walk(resolved, 0);
    return { ok: true, path: resolved, pattern, results, truncated: results.length >= limit };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

const SEARCH_MAX_FILE_BYTES = 512 * 1024;

export function searchFiles(searchPath: string, pattern: string, options: { caseSensitive?: boolean; include?: string; maxResults?: number } = {}): { ok: true; path: string; pattern: string; results: SearchMatch[]; truncated: boolean } | { ok: false; error: string } {
  if (!pattern) return { ok: false, error: "Missing pattern." };
  const resolved = resolvePath(searchPath) || os.homedir();
  const limit = Math.min(options.maxResults ?? 100, 500);

  let regex: RegExp;
  try { regex = new RegExp(pattern, options.caseSensitive ? "" : "i"); }
  catch (err) { return { ok: false, error: `Invalid pattern: ${err instanceof Error ? err.message : String(err)}` }; }

  const results: SearchMatch[] = [];
  function walk(dir: string, depth: number) {
    if (depth > 8 || results.length >= limit) return;
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (results.length >= limit) return;
      if (entry.isDirectory()) {
        if (EXCLUDED_DIRS.has(entry.name)) continue;
        walk(path.join(dir, entry.name), depth + 1);
      } else if (entry.isFile()) {
        const filePath = path.join(dir, entry.name);
        if (options.include && !entry.name.includes(options.include) && !filePath.includes(options.include)) continue;
        let stat: fs.Stats;
        try { stat = fs.statSync(filePath); } catch { continue; }
        if (stat.size > SEARCH_MAX_FILE_BYTES) continue;
        let text: string;
        try { text = fs.readFileSync(filePath, "utf8"); } catch { continue; }
        const lines = text.split("\n");
        for (let i = 0; i < lines.length && results.length < limit; i++) {
          if (regex.test(lines[i]!)) {
            results.push({ file: path.relative(resolved, filePath).replace(/\\/g, "/"), line: i + 1, text: lines[i]!.slice(0, 300) });
          }
        }
      }
    }
  }

  try {
    if (!fs.statSync(resolved).isDirectory()) return { ok: false, error: "path must be a directory." };
    walk(resolved, 0);
    return { ok: true, path: resolved, pattern, results, truncated: results.length >= limit };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}
