import { spawnSync } from "child_process";
import type { ShellPayload, ShellResult } from "./types.js";
import { isAllowedCommand, classifyOperation, buildDescription, validateArgs } from "./security.js";
import { ProcessManager } from "./process-manager.js";
import { resolveWorkspaceCwd } from "./path-policy.js";

const SHELL_TIMEOUT_MS = 60_000;
const STDOUT_MAX = 128 * 1024;
const STDERR_MAX = 32 * 1024;

function buildEnv(): NodeJS.ProcessEnv {
  const src = process.env;
  const keys = process.platform === "win32"
    ? ["APPDATA", "ComSpec", "HOMEDRIVE", "HOMEPATH", "LOCALAPPDATA", "PATH", "PATHEXT",
       "ProgramFiles", "ProgramFiles(x86)", "ProgramW6432", "PYTHONIOENCODING",
       "SystemRoot", "TEMP", "TMP", "USERPROFILE"]
    : ["HOME", "LANG", "LC_ALL", "PATH", "PYTHONIOENCODING", "SHELL", "TEMP", "TMP", "TMPDIR", "USER"];
  const env: NodeJS.ProcessEnv = {};
  for (const key of keys) {
    if (typeof src[key] === "string") env[key] = src[key];
  }
  env.PYTHONIOENCODING = "utf-8";
  return env;
}

export function handleShell(
  payload: ShellPayload,
  workspaceRoot: string,
): ShellResult | { ok: false; error: string } | { ok: true; requiresConfirmation: true; tier: string; description: string } {
  const command = String(payload.command || "").trim();
  const args = Array.isArray(payload.args) ? payload.args.map((a) => String(a)).filter(Boolean) : [];
  const confirmed = payload.confirmed === true;
  const timeoutMs = Math.min(Math.max(Number(payload.timeout) || SHELL_TIMEOUT_MS, 1000), 10 * 60 * 1000);

  if (!command) return { ok: false, error: "Missing command." };
  if (!isAllowedCommand(command, payload.allowedBinaries)) {
    return { ok: false, error: `Command "${command}" is not in the allowed list.` };
  }

  let cwd: string;
  try {
    cwd = resolveWorkspaceCwd(workspaceRoot, payload.cwd);
    validateArgs(command, args, { workspaceRoot, cwd });
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }

  const { tier } = classifyOperation(command, args);
  if ((tier === "network" || tier === "destructive") && !confirmed) {
    return { ok: true, requiresConfirmation: true, tier, description: buildDescription(command, args) };
  }

  const result = spawnSync(command, args, {
    cwd, env: buildEnv(), shell: false, encoding: "utf8",
    timeout: timeoutMs, windowsHide: true, maxBuffer: 4 * 1024 * 1024,
  });

  return {
    ok: true,
    exitCode: typeof result.status === "number" ? result.status : null,
    stdout: (result.stdout || "").slice(0, STDOUT_MAX),
    stderr: (result.stderr || "").slice(0, STDERR_MAX),
    timedOut: result.signal === "SIGTERM" || (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT",
    tier,
    cwd,
  };
}

export { ProcessManager, buildEnv };
